using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
        // Existing documents use "Discriminator", so we must preserve the old property name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
        // Existing documents use "Blog|1" format, so we must opt in to the legacy format.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>()
            .Property(b => b.Id)
            .HasJsonPropertyName("id");
        modelBuilder.Entity<Blog>().UseETagConcurrency();

        // Breaking change 3: EF Core 9 no longer supports indexes on Cosmos (they were silently
        // ignored before; now they throw). Removed HasIndex(b => b.Name).

        // Breaking change 4: EF Core 9 uses id format "Key" by default instead of "EntityType|Key".
        // Existing documents have ids like "Blog|1", so we must opt back into the legacy id format.
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Preserve the legacy "EntityType|KeyValue" id format for existing documents.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Infrastructure.IdValueGeneratorConvention());
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

