{
    void Run(BlogContext context)
    {
        // Breaking change 5: EF Core 9 enables sync-over-async detection by default.
        // Cosmos provider only supports async I/O; sync calls now throw.
        // Migrate all calls to their async equivalents.
        RunAsync(context).GetAwaiter().GetResult();
