using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF 9 renamed the discriminator JSON property from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so preserve the old property name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF 9 no longer includes the discriminator value in the JSON "id".
        // Existing documents have ids like "Blog|1", so opt back in.
        modelBuilder.Entity<Blog>().HasDiscriminatorInJsonId();

        // Breaking change 3: EF 9 maps the C# key directly to JSON "id" instead of a shadow "__id".
        // Existing documents used the shadow property. Force the old behavior.
        modelBuilder.Entity<Blog>().HasShadowId();

        // Breaking change 4: EF 9 no longer silently ignores indexes on Cosmos — it throws.
        // Removed the HasIndex(b => b.Name) call that was here.
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

